<template><section><h3>{{ plural('race.competitors', competitors.length) }}</h3><EmptyState v-if="!competitors.length" :message="t('race.noLineup')" /><div v-else class="scr-competitor-list" v-bng-scoped-nav="{ type: 'container' }"><CompetitorCard v-for="competitor in competitors" :key="competitor.competitorId || competitor.id || competitor.index" :competitor="competitor" @move="move" @failure="failure" @remove="remove" @rename="rename" /></div></section></template>
<script setup>
import { computed } from "vue"; import { vBngScopedNav } from "@/common/directives"; import { useStores } from "../../stores"; import EmptyState from "../common/EmptyState.vue"; import CompetitorCard from "./CompetitorCard.vue"
const stores = useStores(); const { t, plural } = stores.i18n; const competitors = computed(() => stores.race.state.lineup?.current?.competitors || [])
const move = (item, delta) => stores.command.send("reorderLineupCompetitor", [item.index, Math.max(1, Math.min(competitors.value.length, Number(item.position || item.index) + delta))]); const failure = (item, action) => stores.command.send("resolveLineupFailure", [item.index, action]); const remove = item => stores.command.send("removeManagedVehicle", [item.managedHandle]); const rename = (item, value) => stores.command.send("renameLineupCompetitor", [item.index, value])
</script>
